(5713257, 830914, 105130, '<td valign="top">I think the photo itself is wonderful compositionally, but I''m not sure it really fits the theme of the challenge.</td>', 'I think the photo itself is wonderful compositionally, but I''m not sure it really fits the theme of the challenge.', '2009-11-04 06:17:06.000000', NULL, 1),
(5713265, 831101, 105130, '<td valign="top">Brilliant idea, and very well executed - you took the challenge in a different direction than most. I only wish the wine was a bit ''cleaner''.</td>', 'Brilliant idea, and very well executed - you took the challenge in a different direction than most. I only wish the wine was a bit ''cleaner''.', '2009-11-04 06:23:52.000000', NULL, 1),
