(5713291, 831073, 105457, '<td valign="top">Just great!<br/>Love the fact that the guy in the back is holding his head, and the tilt actually adds much more to the photo than just being straight.<br/>Congratulations!</td>', 'Just great!Love the fact that the guy in the back is holding his head, and the tilt actually adds much more to the photo than just being straight.Congratulations!', '2009-11-04 07:00:41.000000', NULL, 1),
(5713292, 831067, 105457, '<td valign="top">Although you lost some details in the downsizing, the contrast is amazing. The play with B&amp;W is simply outstanding.<br/>Greta one!</td>', 'Although you lost some details in the downsizing, the contrast is amazing. The play with B&W is simply outstanding.Greta one!', '2009-11-04 07:01:30.000000', NULL, 1),
